insert into public.events (title, slug, summary, description, event_date, published_at, date_type, category, cover_image, status) values ('Réaménagement de l’école Agdou rkik', '2022-agdou-rkik', 'Sous le thème « Une action sociale pour une école rurale », le Club de Solidarité Elaraki a repris les travaux de réaménagement de l’école Agdou rkik. Le 27 novembre 2022, les élèv', 'Sous le thème « Une action sociale pour une école rurale », le Club de Solidarité Elaraki a repris les travaux de réaménagement de l’école Agdou rkik. Le 27 novembre 2022, les élèves des deux établissements se sont donné la main afin de construire des liens de fraternité et d’aménager un espace où la dignité est respectée.', '2022-12-13', now(), 'reference', 'Éducation', '/assets/events/2022-agdou-rkik/01-317078796-2271674943000656-2559266695478534620-n.jpg', 'published') on conflict (slug) do nothing;
insert into public.events (title, slug, summary, description, event_date, published_at, date_type, category, cover_image, status) values ('Un Iftar solidaire au service de l’éducation', '2022-iftar-solidaire', 'Le club de solidarité de l’établissement international ELARAKI a organisé un Iftar solidaire auquel les élèves ont participé avec enthousiasme. Cette initiative visait à contribuer', 'Le club de solidarité de l’établissement international ELARAKI a organisé un Iftar solidaire auquel les élèves ont participé avec enthousiasme. Cette initiative visait à contribuer aux travaux de rénovation de l’établissement rural Akdourkik, afin d’améliorer ses installations et les conditions d’apprentissage.', '2022-04-28', now(), 'reference', 'Solidarité', '/assets/events/2022-iftar-solidaire/01-278573513-10224325629421484-2823121452570116615-n.jpg', 'published') on conflict (slug) do nothing;
insert into public.events (title, slug, summary, description, event_date, published_at, date_type, category, cover_image, status) values ('Rénovation et animation à l’école Ighalen', '2019-ighalen', 'Les générations changent mais l’esprit du Club de Solidarité reste immuable. Les élèves sont retournés à Tighdouine pour renouer le contact avec les habitants et poursuivre les act', 'Les générations changent mais l’esprit du Club de Solidarité reste immuable. Les élèves sont retournés à Tighdouine pour renouer le contact avec les habitants et poursuivre les actions initiées par les générations précédentes : peinture des murs, équipement de la bibliothèque, animations et distribution de cadeaux.', '2019-04-16', now(), 'reference', 'Éducation', '/assets/events/2019-ighalen/01-910084c4eb3461ee8947cd42bdd4b146-XL.jpg', 'published') on conflict (slug) do nothing;
insert into public.events (title, slug, summary, description, event_date, published_at, date_type, category, cover_image, status) values ('ELARAKI’s Got Talent — Un moment de partage', '2019-got-talent', 'Un événement artistique et culturel réunissant la communauté scolaire autour de talents variés. Les archives remercient les participants et mentionnent la victoire d’Intissar Eddaj', 'Un événement artistique et culturel réunissant la communauté scolaire autour de talents variés. Les archives remercient les participants et mentionnent la victoire d’Intissar Eddajraoui, récompensée par le premier prix. La date exacte de tenue n’est pas confirmée par les documents disponibles.', '2019-03-13', now(), 'reference', 'Culture', '/assets/events/2019-got-talent/01-53026322-1177842245717270-4674453134347599872-o.jpg', 'published') on conflict (slug) do nothing;
insert into public.events (title, slug, summary, description, event_date, published_at, date_type, category, cover_image, status) values ('Campagne de don du sang', '2018-don-du-sang', 'Une initiative citoyenne organisée au sein de l’établissement pour sensibiliser à l’importance du don du sang et encourager les gestes solidaires en faveur de la santé publique.', 'Une initiative citoyenne organisée au sein de l’établissement pour sensibiliser à l’importance du don du sang et encourager les gestes solidaires en faveur de la santé publique.', '2018-11-19', now(), 'reference', 'Santé', '/assets/events/2018-don-du-sang/01-46389010-1107060849462077-6311714166734323712-o.jpg', 'published') on conflict (slug) do nothing;
insert into public.events (title, slug, summary, description, event_date, published_at, date_type, category, cover_image, status) values ('Finalisation des travaux à l’école rurale Masstour', '2018-masstour', 'Finalisation des travaux de construction d’une cour et d’un mur de clôture réalisés par les Aigles du Club de Solidarité ELARAKI Ennakhil à l’école rurale Masstour, dans la région ', 'Finalisation des travaux de construction d’une cour et d’un mur de clôture réalisés par les Aigles du Club de Solidarité ELARAKI Ennakhil à l’école rurale Masstour, dans la région de Tighdouine.', '2018-05-16', now(), 'reference', 'Travaux et rénovation', '/assets/events/2018-masstour/01-0008.jpg', 'published') on conflict (slug) do nothing;
